#include <zephyr/kernel.h>
#include <zephyr/init.h>
#include <ksched.h>
#include <wait_q.h>
#include <zephyr/sys/dlist.h>
#include <zephyr/sys/math_extras.h>
#include <zephyr/sys/mem_manage.h>
#include <zephyr/sys/iterable_sections.h>
#include <zephyr/logging/log.h>
#include <string.h>
LOG_MODULE_DECLARE(os, CONFIG_KERNEL_LOG_LEVEL);

void k_heap_init(struct k_heap *h, void *mem, size_t bytes)
{
	z_waitq_init(&h->wait_q);
	sys_heap_init(&h->heap, mem, bytes);

	SYS_PORT_TRACING_OBJ_INIT(k_heap, h);
}

static int statics_init(void)
{
	STRUCT_SECTION_FOREACH(k_heap, h) {
#if defined(CONFIG_DEMAND_PAGING) && !defined(CONFIG_LINKER_GENERIC_SECTIONS_PRESENT_AT_BOOT)
		/* Some heaps may be present at boot, so we need to check the Status
		 * before the paging mechanism is initialized.
		 */
		bool is_present =
			k_mem_page_frames_is_paged((uintptr_t)h->heap.init_mem, h->heap.init_bytes);

		if (!is_present) {
			continue;
		}
#endif /* CONFIG_DEMAND_PAGING && !CONFIG_LINKER_GENERIC_SECTIONS_PRESENT_AT_BOOT */
		k_heap_init(h, h->heap.init_mem, h->heap.init_bytes);
	}
	return 0;
}

SYS_INIT(statics_init, PRE_KERNEL_1, CONFIG_KERNEL_INIT_PRIORITY_OBJECTS);

#if defined(CONFIG_DEMAND_PAGING) && !defined(CONFIG_LINKER_GENERIC_SECTIONS_PRESENT_AT_BOOT)
/* Need to wait for paging mechanism to be initialized before
 * heaps that are not present at boot can be initialized.
 */
static int statics_init_post_paging(void)
{
	STRUCT_SECTION_FOREACH(k_heap, h) {
		/* Only initialize heaps that were not initialized in PRE_KERNEL_1 */
		if (h->heap.heap == NULL) {
			k_heap_init(h, h->heap.init_mem, h->heap.init_bytes);
		}
	}

	return 0;
}

SYS_INIT(statics_init_post_paging, POST_KERNEL, CONFIG_KERNEL_INIT_PRIORITY_OBJECTS);
#endif /* CONFIG_DEMAND_PAGING && !CONFIG_LINKER_GENERIC_SECTIONS_PRESENT_AT_BOOT */

void *k_heap_aligned_alloc(struct k_heap *h, size_t align, size_t bytes,
			   k_timeout_t timeout)
{
	int64_t now, end = sys_clock_timeout_end_calc(timeout);
	void *ret = NULL;

	k_spinlock_key_t key = k_spin_lock(&h->lock);

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_heap, aligned_alloc, h, timeout);

	__ASSERT(!arch_is_in_isr() || K_TIMEOUT_EQ(timeout, K_NO_WAIT), "");

	bool blocked_alloc = false;

	while (ret == NULL) {
		ret = sys_heap_aligned_alloc(&h->heap, align, bytes);

		if (!IS_ENABLED(CONFIG_MULTITHREADING) ||
		    (ret != NULL) || K_TIMEOUT_EQ(timeout, K_NO_WAIT)) {
			break;
		}

		now = sys_clock_tick_get();
		if ((end - now) <= 0) {
			break;
		}

		if (!blocked_alloc) {
			blocked_alloc = true;

			SYS_PORT_TRACING_OBJ_FUNC_BLOCKING(k_heap, aligned_alloc, h, timeout);
		} else {
			/**
			 * @todo	Trace attempt to avoid empty trace segments
			 */
		}

		(void) z_pend_curr(&h->lock, key, &h->wait_q,
				   K_TICKS(end - now));
		key = k_spin_lock(&h->lock);
	}

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_heap, aligned_alloc, h, timeout, ret);

	k_spin_unlock(&h->lock, key);
	return ret;
}

void *k_heap_alloc(struct k_heap *h, size_t bytes, k_timeout_t timeout)
{
	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_heap, alloc, h, timeout);

	void *ret = k_heap_aligned_alloc(h, sizeof(void *), bytes, timeout);

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_heap, alloc, h, timeout, ret);

	return ret;
}

void *k_heap_calloc(struct k_heap *h, size_t num, size_t size, k_timeout_t timeout)
{
	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_heap, calloc, h, timeout);

	void *ret = NULL;
	size_t bounds = 0U;

	if (!size_mul_overflow(num, size, &bounds)) {
		ret = k_heap_alloc(h, bounds, timeout);
	}
	if (ret != NULL) {
		(void)memset(ret, 0, bounds);
	}

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_heap, calloc, h, timeout, ret);

	return ret;
}

void *k_heap_realloc(struct k_heap *h, void *ptr, size_t bytes, k_timeout_t timeout)
{
	int64_t now, end = sys_clock_timeout_end_calc(timeout);
	void *ret = NULL;

	k_spinlock_key_t key = k_spin_lock(&h->lock);

	SYS_PORT_TRACING_OBJ_FUNC_ENTER(k_heap, realloc, h, ptr, bytes, timeout);

	__ASSERT(!arch_is_in_isr() || K_TIMEOUT_EQ(timeout, K_NO_WAIT), "");

	while (ret == NULL) {
		ret = sys_heap_aligned_realloc(&h->heap, ptr, sizeof(void *), bytes);

		if (!IS_ENABLED(CONFIG_MULTITHREADING) ||
		    (ret != NULL) || K_TIMEOUT_EQ(timeout, K_NO_WAIT)) {
			break;
		}

		now = sys_clock_tick_get();
		if ((end - now) <= 0) {
			break;
		}

		(void) z_pend_curr(&h->lock, key, &h->wait_q,
				   K_TICKS(end - now));
		key = k_spin_lock(&h->lock);
	}

	SYS_PORT_TRACING_OBJ_FUNC_EXIT(k_heap, realloc, h, ptr, bytes, timeout, ret);

	k_spin_unlock(&h->lock, key);
	return ret;
}

void k_heap_free(struct k_heap *h, void *mem)
{
	k_spinlock_key_t key = k_spin_lock(&h->lock);

	sys_heap_free(&h->heap, mem);

	SYS_PORT_TRACING_OBJ_FUNC_ (k_heap, free, h);
	if (IS_ENABLED(CONFIG_MULTITHREADING) && z_unpend_all(&h->wait_q) != 0) {
		z_reschedule(&h->lock, key);
	} else {
		k_spin_unlock(&h->lock, key);
	}
}

int k_heap_array_get(struct k_heap **heap)
{
	/* Point to the start of the heap array */
	STRUCT_SECTION_GET(k_heap, 0, heap);
	/* Return the number of heaps in the array */
	int num;
	STRUCT_SECTION_COUNT(k_heap, &num);
	return num;
}

#if (CONFIG_HEAP_MEM_POOL_SIZE > 0)

/*
 *Custom k_heap_MEM_POOL_SIZE configuration options are used to
 *create an application system heap.
 */
#define HEAP_MEM_POOL_ADD_SIZE  (CONFIG_HEAP_MEM_POOL_ADD_SIZE_ACPI + \
				 CONFIG_HEAP_MEM_POOL_ADD_SIZE_IPC + \
				 CONFIG_HEAP_MEM_POOL_ADD_SIZE_MBEDTLS + \
				 CONFIG_HEAP_MEM_POOL_ADD_SIZE_POSIX_SI + \
				 CONFIG_HEAP_MEM_POOL_ADD_SIZE_POSIX_TIMERS + \
				 CONFIG_HEAP_MEM_POOL_ADD_SIZE_SOF + \
				 CONFIG_HEAP_MEM_POOL_ADD_SIZE_WAYLAND)

#if (CONFIG_HEAP_MEM_POOL_SIZE < HEAP_MEM_POOL_ADD_SIZE) && \
	!defined(CONFIG_HEAP_MEM_POOL_IGNORE_MIN)
#errorTotal size of required add-ons exceeds maximum size of the heap memory pool.\
Please adjust CONFIG_HEAP_MEM_POOL_SIZE in your configuration file.\
Alternatively, enable CONFIG_HEAP_MEM_POOL_IGNORE_MIN to ignore the minimum\
size requirement from modules.
#define _HEAP_MEM_POOL_SIZE HEAP_MEM_POOL_ADD_SIZE
#else
#define _HEAP_MEM_POOL_SIZE CONFIG_HEAP_MEM_POOL_SIZE
#endif

K_HEAP_DEFINE(_system_heap, _HEAP_MEM_POOL_SIZE);
#define _SYSTEM_HEAP (&_system_heap)

void *z_thread_aligned_alloc(size_t align, size_t size)
{
	void *ret;
	struct k_heap *heap;

	if (k_is_in_isr()) {
		heap = _SYSTEM_HEAP;
	} else {
		heap = _current->resource_pool;
	}

	if (heap) {
		ret = k_heap_aligned_alloc(heap, align, size, K_NO_WAIT);
	} else {
		ret = NULL;
	}

	return ret;
}

void *k_aligned_alloc(size_t align, size_t size)
{
	SYS_PORT_TRACING_FUNC_ENTER(k_heap_sys, k_aligned_alloc, _SYSTEM_HEAP, align, size);

	void *ret = k_heap_aligned_alloc(_SYSTEM_HEAP, align, size, K_NO_WAIT);

	SYS_PORT_TRACING_FUNC_EXIT(k_heap_sys, k_aligned_alloc, _SYSTEM_HEAP, ret);

	return ret;
}

void *k_malloc(size_t size)
{
	SYS_PORT_TRACING_FUNC_ENTER(k_heap_sys, k_malloc, _SYSTEM_HEAP, size);

	void *ret = k_aligned_alloc(sizeof(void *), size);

	SYS_PORT_TRACING_FUNC_EXIT(k_heap_sys, k_malloc, _SYSTEM_HEAP, ret);

	return ret;
}

void *k_realloc(void *ptr, size_t size)
{
	SYS_PORT_TRACING_FUNC_ENTER(k_heap_sys, k_realloc, _SYSTEM_HEAP, ptr, size);

	void *ret = k_heap_realloc(_SYSTEM_HEAP, ptr, size, K_NO_WAIT);

	SYS_PORT_TRACING_FUNC_EXIT(k_heap_sys, k_realloc, _SYSTEM_HEAP, ret);

	return ret;
}

void k_free(void *ptr)
{
	SYS_PORT_TRACING_FUNC_ENTER(k_heap_sys, k_free, _SYSTEM_HEAP, _SYSTEM_HEAP);

	k_heap_free(_SYSTEM_HEAP, ptr);

	SYS_PORT_TRACING_FUNC_EXIT(k_heap_sys, k_free, _SYSTEM_HEAP);
}

void *k_calloc(size_t nmemb, size_t size)
{
	SYS_PORT_TRACING_FUNC_ENTER(k_heap_sys, k_calloc, _SYSTEM_HEAP, nmemb, size);

	void *ret = k_heap_calloc(_SYSTEM_HEAP, nmemb, size, K_NO_WAIT);

	SYS_PORT_TRACING_FUNC_EXIT(k_heap_sys, k_calloc, _SYSTEM_HEAP, ret);

	return ret;
}

void k_thread_system_pool_assign(struct k_thread *thread)
{
	thread->resource_pool = _SYSTEM_HEAP;
}
#else
void *z_thread_aligned_alloc(size_t align, size_t size)
{
	void *ret;
	struct k_heap *heap;

	if (k_is_in_isr()) {
		return NULL;
	}

	heap = _current->resource_pool;

	if (heap) {
		ret = k_heap_aligned_alloc(heap, align, size, K_NO_WAIT);
	} else {
		ret = NULL;
	}

	return ret;
}
#endif /* CONFIG_HEAP_MEM_POOL_SIZE */

void *z_thread_malloc(size_t size)
{
	return z_thread_aligned_alloc(sizeof(void *), size);
}
